class Proxy
  def initialize(target)
    @target = target
  end

  def respond_to?(name, include_private = false)
    return true if @target.respond_to?(name, include_private)
    # Check if the method is defined on this Proxy class or ancestor
    begin
      method(name)
      true
    rescue NameError
      false
    end
  end

  def method(name)
    if @target.respond_to?(name)
      # Return a proc that calls the method on the target
      Proc.new { |*args, **kwargs, &block| @target.send(name, *args, **kwargs, &block) }
    else
      raise NameError.new("undefined method `#{name}' for class `#{self.class.name || 'Object'}'")
    end
  end

  def method_missing(name, *args, **kwargs, &block)
    if @target.respond_to?(name)
      @target.send(name, *args, **kwargs, &block)
    else
      super
    end
  end
end
