class Cache
  def initialize(packer: nil)
    @packer = packer
    @entries = {}
    @order = []
  end

  def write(key, payload, stale: false)
    payload_to_store = @packer ? @packer.dump(payload) : payload
    if @entries.key?(key)
      # Remove from order if already present to re-insert at end
      @order.delete(key)
    end
    @entries[key] = { payload: payload_to_store, stale: stale }
    @order << key
  end

  def read(key)
    return nil unless @entries.key?(key)

    entry = @entries[key]
    payload_stored = entry[:payload]

    payload = @packer ? @packer.load(payload_stored) : payload_stored
    payload
  end

  def sweep
    to_remove = []
    @order.each do |key|
      next unless @entries.key?(key)
      if @entries[key][:stale]
        to_remove << key
      end
    end
    to_remove.each do |key|
      @entries.delete(key)
      @order.delete(key)
    end
  end
end
