  def initialize(target)
    @target = target
  end

  def respond_to?(name, include_private = false)
    return true if @target.respond_to?(name, include_private)
    # Check if Proxy itself defines the method
    methods = (self.class.instance_methods + Object.methods).include?(name.to_s)
    return true if methods

    # For specific built-in methods that should always work
    %w[to_s inspect object_id class to_i to_s hash eql? == ===].include?(name.to_s)
  end

  def method(name)
    raise NameError, "undefined method `#{name}' for #{self.inspect}" unless respond_to?(name)

    proc do |*args, &block|
      @target.send(name, *args, &block)
    end
  end

  def method_missing(name, *args, &block)
    if @target.respond_to?(name)
      @target.send(name, *args, &block)
    else
      raise NoMethodError, "undefined method `#{name}' for #{self.inspect}"
