class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      @attributes[key] = value
    end

    # Define getter methods for provided attributes
    attrs.each_key do |key|
      define_getter(key)
      define_setter(key)
    end
  end

  def method_missing(method_name, *args, &block)
    if method_name.to_s.end_with?('=') && args.length == 1
      attr_name = method_name.to_s.chomp('=').to_sym
      @attributes[attr_name] = args.first
      define_getter(attr_name)
      define_setter(attr_name)
      return args.first
    elsif !method_name.to_s.end_with?('=')
      if @attributes.key?(method_name)
        return @attributes[method_name]
      end
    end
    super
  end

  def respond_to_missing?(method_name, include_private = false)
    method_str = method_name.to_s
    if method_str.end_with?('=')
      attr_name = method_str.chomp('=').to_sym
      @attributes.key?(attr_name)
    else
      @attributes.key?(method_name)
    end
  end

  private

  def define_getter(name)
    self.class.define_method(name) do
      @attributes[name]
    end
  end

  def define_setter(name)
    self.class.define_method("#{name}=") do |value|
      @attributes[name] = value
    end
  end
end
