class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      @attributes[key] = value
      define_attribute_accessor(key)
    end
  end

  def respond_to?(method_name, include_private = false)
    return true if method_name.to_s.end_with?('=') && attribute_from_method(method_name.to_s.chomp('='))
    return true if attribute?(method_name.to_sym)
    super
  end

  private

  def attribute?(name)
    @attributes.key?(name)
  end

  def attribute_from_method(name)
    name.to_sym
  end

  def define_attribute_accessor(name)
    define_singleton_method(name) { @attributes[name] }
    define_singleton_method("#{name}=") do |value|
      @attributes[name] = value
      define_singleton_method(name) { @attributes[name] } unless @attributes.key?(name)
      value
    end
  end

  # Handle method calls for attributes not yet defined but which might be set via assignment
  def method_missing(method_name, *args, &block)
    if args.empty? && method_name.to_s[-1] != '='
      if @attributes.key?(method_name)
        @attributes[method_name]
      else
        super
      end
    elsif method_name.to_s.end_with?('=') && args.length == 1
      name = method_name.to_s.chomp('=').to_sym
      @attributes[name] = args.first
      # Define the getter so subsequent reads work directly
      define_singleton_method(name) { @attributes[name] }
      # Ensure respond_to picks it up immediately
      define_singleton_method(name) unless @attributes.key?(name)
      args.first
    else
      super
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    if method_name.to_s.end_with?('=')
      true
    elsif !method_name.to_s.empty?
      true
    else
      false
    end
  end
end
